     1→/* Context-based theming for B2C and B2B interfaces */
     2→
     3→/* B2C Theme - Emotional and warm */
     4→.theme-b2c {
     5→  /* Color variants for B2C */
     6→  --blue-25: hsl(221, 100%, 97%);
     7→  --orange-25: hsl(34, 100%, 97%);
     8→  --red-25: hsl(350, 100%, 97%);
     9→  --green-25: hsl(142, 100%, 97%);
    10→  --purple-25: hsl(270, 100%, 97%);
    11→  --yellow-25: hsl(45, 100%, 97%);
    12→  --pink-25: hsl(320, 100%, 97%);
    13→
    14→  /* B2C specific spacing and layout */
    15→  --spacing-card: 1.5rem;
    16→  --spacing-section: 2rem;
    17→  --radius-card: 0.75rem;
    18→  --shadow-card:
    19→    0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
    20→}
    21→
    22→/* B2B Theme - Professional and compact */
    23→.theme-b2b {
    24→  /* Color variants for B2B */
    25→  --slate-25: hsl(210, 40%, 98%);
    26→  --slate-150: hsl(210, 40%, 94%);
    27→  --blue-25: hsl(215, 100%, 97%);
    28→  --green-25: hsl(142, 100%, 97%);
    29→  --yellow-25: hsl(45, 100%, 97%);
    30→  --orange-25: hsl(34, 100%, 97%);
    31→  --red-25: hsl(350, 100%, 97%);
    32→  --indigo-25: hsl(225, 100%, 97%);
    33→
    34→  /* B2B specific spacing and layout */
    35→  --spacing-card: 1rem;
    36→  --spacing-section: 1.5rem;
    37→  --radius-card: 0.375rem;
    38→  --shadow-card: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
    39→}
    40→
    41→/* Responsive theme adjustments */
    42→@media (max-width: 768px) {
    43→  .theme-b2c {
    44→    --spacing-card: 1rem;
    45→    --spacing-section: 1.5rem;
    46→  }
    47→
    48→  .theme-b2b {
    49→    --spacing-card: 0.75rem;
    50→    --spacing-section: 1rem;
    51→  }
    52→}
    53→
    54→/* Animation preferences based on context */
    55→.theme-b2c * {
    56→  transition-duration: 200ms;
    57→}
    58→
    59→.theme-b2b * {
    60→  transition-duration: 150ms;
    61→}
    62→
    63→/* Font weight adjustments */
    64→.theme-b2c h1,
    65→.theme-b2c h2,
    66→.theme-b2c h3 {
    67→  font-weight: 600;
    68→}
    69→
    70→.theme-b2b h1,
    71→.theme-b2b h2,
    72→.theme-b2b h3 {
    73→  font-weight: 700;
    74→}
    75→

