     8→import type { LayoutParams } from "@/types/next";
     9→import type { Metadata } from "next";
    10→import { Geist_Mono, Inter, Space_Grotesk } from "next/font/google";
    11→import { NuqsAdapter } from "nuqs/adapters/next/app";
    12→import { type ReactNode, Suspense } from "react";
    13→import "./globals.css";
    14→import { Providers } from "./providers";
    15→
    16→export const metadata: Metadata = {
    17→  title: SiteConfig.title,
    18→  description: SiteConfig.description,
    19→  metadataBase: new URL(getServerUrl()),
    20→};
    21→
    22→const CaptionFont = Space_Grotesk({
    23→  subsets: ["latin"],
    24→  variable: "--font-caption",
    25→});
    26→
    27→const GeistSans = Inter({
    28→  subsets: ["latin"],
    29→  variable: "--font-geist-sans",
    30→});
    31→
    32→const GeistMono = Geist_Mono({
    33→  subsets: ["latin"],
    34→  variable: "--font-geist-mono",
