     1→"use client";
     2→
     3→import { Button } from "@/components/ui/button";
     4→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
     5→import {
     6→  Table,
     7→  TableBody,
     8→  TableCell,
     9→  TableHead,
    10→  TableHeader,
    11→  TableRow,
    12→} from "@/components/ui/table";
    13→import { X, FileText, Trash2 } from "lucide-react";
    14→import { useState } from "react";
    15→import { SafeImage } from "@/components/ui/safe-image";
    16→import {
    17→  COMPARISON_METRICS,
    18→  type ComparisonProperty,
    19→  type ComparisonMetric,
    20→} from "./types";
    21→
    22→type ComparisonTableProps = {
    23→  properties: ComparisonProperty[];
    24→  onRemoveProperty: (propertyId: string) => void;
    25→  onClearAll: () => void;
    26→  onExportPDF?: () => void;
    27→};
    28→
    29→export function ComparisonTable({
    30→  properties,
    31→  onRemoveProperty,
    32→  onClearAll,
    33→  onExportPDF,
    34→}: ComparisonTableProps) {
    35→  const [highlightBest, setHighlightBest] = useState(true);
    36→
    37→  if (properties.length === 0) {
    38→    return (
    39→      <Card>
    40→        <CardContent className="flex flex-col items-center justify-center py-12">
    41→          <p className="text-muted-foreground">
    42→            Aucun bien sélectionné pour la comparaison
    43→          </p>
    44→          <p className="text-muted-foreground mt-2 text-sm">
    45→            Ajoutez des biens depuis la recherche pour les comparer
    46→          </p>
    47→        </CardContent>
    48→      </Card>
    49→    );
    50→  }
    51→
    52→  const formatValue = (value: unknown, type: string): string => {
    53→    if (value === null || value === undefined) return "N/A";
    54→
    55→    switch (type) {
    56→      case "currency":
    57→        return new Intl.NumberFormat("fr-FR", {
    58→          style: "currency",
    59→          currency: "EUR",
    60→          minimumFractionDigits: 0,
    61→        }).format(value as number);
    62→      case "surface":
    63→        return `${value} m²`;
    64→      case "energy":
    65→        return value as string;
    66→      case "number":
    67→        return value.toString();
    68→      case "boolean":
    69→        return (value as boolean) ? "Oui" : "Non";
    70→      default:
    71→        return value.toString();
    72→    }
    73→  };
    74→
    75→  const getBestValue = (metric: ComparisonMetric, values: unknown[]) => {
    76→    const validValues = values.filter((v) => v !== null && v !== undefined);
    77→    if (validValues.length === 0) return null;
    78→
    79→    switch (metric.type) {
    80→      case "currency":
    81→        return Math.min(...(validValues as number[]));
    82→      case "surface":
    83→      case "number":
    84→        return Math.max(...(validValues as number[]));
    85→      case "energy": {
    86→        const energyOrder = ["A", "B", "C", "D", "E", "F", "G"];
    87→        return validValues.reduce((best, current) => {
    88→          const bestIndex = energyOrder.indexOf(best as string);
    89→          const currentIndex = energyOrder.indexOf(current as string);
    90→          return currentIndex < bestIndex || bestIndex === -1 ? current : best;
    91→        });
    92→      }
    93→      default:
    94→        return null;
    95→    }
    96→  };
    97→
    98→  const isHighlighted = (
    99→    value: unknown,
   100→    metric: ComparisonMetric,
   101→    allValues: unknown[],
   102→  ) => {
   103→    if (!highlightBest || value === null || value === undefined) return false;
   104→    const bestValue = getBestValue(metric, allValues);
   105→    return value === bestValue;
   106→  };
   107→
   108→  return (
   109→    <Card>
   110→      <CardHeader>
   111→        <div className="flex items-center justify-between">
   112→          <CardTitle>Comparaison de biens ({properties.length})</CardTitle>
   113→          <div className="flex items-center gap-2">
   114→            <Button
   115→              variant="outline"
   116→              size="sm"
   117→              onClick={() => setHighlightBest(!highlightBest)}
   118→            >
   119→              {highlightBest ? "Masquer" : "Afficher"} les meilleures valeurs
   120→            </Button>
   121→            {onExportPDF && (
   122→              <Button variant="outline" size="sm" onClick={onExportPDF}>
   123→                <FileText className="mr-2 h-4 w-4" />
   124→                Export PDF
   125→              </Button>
   126→            )}
   127→            <Button variant="outline" size="sm" onClick={onClearAll}>
   128→              <Trash2 className="mr-2 h-4 w-4" />
   129→              Tout effacer
   130→            </Button>
   131→          </div>
   132→        </div>
   133→      </CardHeader>
   134→      <CardContent>
   135→        <div className="overflow-x-auto">
   136→          <Table>
   137→            <TableHeader>
   138→              <TableRow>
   139→                <TableHead className="bg-background sticky left-0 w-48">
   140→                  Critère
   141→                </TableHead>
   142→                {properties.map((property) => (
   143→                  <TableHead key={property.uniqueId} className="min-w-[200px]">
   144→                    <div className="flex items-start justify-between gap-2">
   145→                      <div className="min-w-0 flex-1">
   146→                        <div className="relative mb-2 aspect-video overflow-hidden rounded">
   147→                          <SafeImage
   148→                            src={property.mainImage ?? property.images[0]}
   149→                            alt={property.title}
   150→                            fill
   151→                            className="object-cover"
   152→                          />
   153→                        </div>
   154→                        <p className="truncate text-sm font-medium">
   155→                          {property.title}
   156→                        </p>
   157→                        <p className="text-muted-foreground text-xs">
   158→                          {property.city}
   159→                        </p>
   160→                      </div>
   161→                      <Button
   162→                        variant="ghost"
   163→                        size="sm"
   164→                        onClick={() => onRemoveProperty(property.uniqueId)}
   165→                        className="h-6 w-6 flex-shrink-0 p-0"
   166→                      >
   167→                        <X className="h-4 w-4" />
   168→                      </Button>
   169→                    </div>
   170→                  </TableHead>
   171→                ))}
   172→              </TableRow>
   173→            </TableHeader>
   174→            <TableBody>
   175→              {COMPARISON_METRICS.map((metric) => {
   176→                const values = properties.map(
   177→                  (property) => property[metric.key],
   178→                );
   179→
   180→                return (
   181→                  <TableRow key={metric.key}>
   182→                    <TableCell className="bg-background sticky left-0 font-medium">
   183→                      {metric.label}
   184→                      {metric.isImportant && (
   185→                        <span className="text-primary ml-1">*</span>
   186→                      )}
   187→                    </TableCell>
   188→                    {properties.map((property, index) => {
   189→                      const value = values[index];
   190→                      const isHighlight = isHighlighted(value, metric, values);
   191→
   192→                      return (
   193→                        <TableCell
   194→                          key={property.uniqueId}
   195→                          className={
   196→                            isHighlight && highlightBest
   197→                              ? "border border-green-200 bg-green-50 font-medium text-green-700"
   198→                              : ""
   199→                          }
   200→                        >
   201→                          {formatValue(value, metric.type)}
   202→                        </TableCell>
   203→                      );
   204→                    })}
   205→                  </TableRow>
   206→                );
   207→              })}
   208→            </TableBody>
   209→          </Table>
   210→        </div>
   211→        <div className="text-muted-foreground mt-4 flex items-center gap-2 text-sm">
   212→          <span>* Critères importants</span>
   213→          {highlightBest && (
   214→            <>
   215→              <span>•</span>
   216→              <span className="flex items-center gap-1">
   217→                <div className="h-3 w-3 rounded bg-green-200"></div>
   218→                Meilleures valeurs
   219→              </span>
   220→            </>
   221→          )}
   222→        </div>
   223→      </CardContent>
   224→    </Card>
   225→  );
   226→}
   227→

